/* BarberCommon Ads v1 — shared, dependency-free in-game interstitials for Avi & Koko. */
(function (root) {
  'use strict';
  if (root.BarberCommonAds) return;

  const STORAGE_KEY = 'barberCommon:ads:v1';
  const COPY = {
    title: 'אבי × קוקו',
    sub: 'המספרה היחידה שבה גם המודעה מספרת בדיחות',
    remove: '🎁 הסר פרסומות',
    gift: 'יאללה קח בחינם, העיקר הבריאות והתסרוקת',
    continue: 'ממשיכים לשחק!'
  };
  const AD_IMAGE = 'data:image/webp;base64,';
  const DEFAULTS = Object.freeze({ gameId: 'barberGame', deathsPerAd: 2, durationSeconds: 15, skipAfterSeconds: 5, minIntervalMs: 0, playerId: null });
  const STYLE = `
    .bc-ad-cover,.bc-ad-gift{position:fixed!important;inset:0!important;z-index:2147483000!important;display:flex;align-items:center;justify-content:center;box-sizing:border-box;padding:calc(12px + env(safe-area-inset-top)) 12px calc(12px + env(safe-area-inset-bottom));background:#060711ed;color:#fff;font:600 15px system-ui,-apple-system,Arial,sans-serif;direction:rtl;overscroll-behavior:contain;touch-action:manipulation;}
    .bc-ad-cover *, .bc-ad-gift *{box-sizing:border-box}
    .bc-ad-panel{position:relative;width:min(100%,380px);height:min(100%,775px);display:flex;flex-direction:column;gap:8px;border-radius:22px;padding:12px;overflow:hidden;border:1px solid #fff5;background:linear-gradient(165deg,#312637,#111623);box-shadow:0 16px 60px #000b;}
    .bc-ad-head{display:flex;align-items:center;justify-content:space-between;gap:9px;min-height:32px;}
    .bc-ad-head strong{font-size:16px;color:#f8db8e}.bc-ad-head span{font-size:12px;color:#ddd;letter-spacing:.3px}
    .bc-ad-video{position:relative;flex:1;min-height:0;display:flex;justify-content:center;align-items:center;overflow:hidden;border-radius:16px;background:#15151b}
    .bc-ad-video img{height:100%;max-width:100%;width:auto;object-fit:contain;display:block}
    .bc-ad-countdown{text-align:center;color:#f0dcb0;min-height:18px;font-size:13px}
    .bc-ad-track{height:5px;background:#ffffff38;overflow:hidden;border-radius:50px}
    .bc-ad-progress{height:100%;width:0;background:#ffd684;border-radius:50px}
    .bc-ad-skip,.bc-ad-remove,.bc-ad-gift button{appearance:none;border:0;border-radius:13px;padding:12px 15px;min-height:43px;font:800 15px system-ui,-apple-system,Arial,sans-serif;cursor:pointer;}
    .bc-ad-skip{color:#fff;background:#28344f;border:1px solid #ffffff4f}.bc-ad-skip:disabled{color:#acadb9;background:#363643;opacity:1;cursor:default}
    .bc-ad-remove{color:#1a2635;background:#f4d389}
    .bc-ad-gift .bc-ad-gift-card{width:min(100%,390px);background:#191f31;border:1px solid #f3d391a8;border-radius:24px;padding:28px 22px;box-shadow:0 18px 50px #0009;text-align:center}
    .bc-ad-gift .bc-ad-gift-emoji{font-size:55px;margin-bottom:8px}.bc-ad-gift h2{font-size:24px;line-height:1.3;color:#ffdda0;margin:8px 0 13px}.bc-ad-gift p{font-size:15px;color:#ddd;line-height:1.6;margin:0 0 20px}.bc-ad-gift button{background:#f6d48f;color:#141c28;width:100%}
    @media (max-height:590px){.bc-ad-cover{padding:5px 10px}.bc-ad-panel{padding:7px;gap:5px;border-radius:14px}.bc-ad-head{min-height:22px}.bc-ad-skip,.bc-ad-remove{min-height:34px;padding:6px}}
  `;
  let styleInjected=false;
  let currentOverlay=null;
  const defaultState=()=>({adFree:{}, deaths:{}, lastShown:{}});
  function load() {
    try { const parsed=JSON.parse(localStorage.getItem(STORAGE_KEY));
      if(parsed && typeof parsed==='object')return {adFree:parsed.adFree||{},deaths:parsed.deaths||{},lastShown:parsed.lastShown||{}};
    }catch(e){}
    return defaultState();
  }
  function save(state) { try { localStorage.setItem(STORAGE_KEY,JSON.stringify(state)); } catch(e) {} }
  function insertStyle(){ if(styleInjected)return;let st=document.createElement('style');st.id='bc-ad-style';st.textContent=STYLE;document.head.appendChild(st);styleInjected=true;}
  function normalizePlayer(v){const s=String(v===undefined||v===null?'guest':v).trim();return s.length?s.slice(0,120):'guest';}
  function makeNode(cls, html){const el=document.createElement('div');el.className=cls;el.innerHTML=html;document.body.appendChild(el);return el;}
  function showGift(playerKey){
    insertStyle();
    if(currentOverlay){currentOverlay.close('ad-free');}
    const state=load();state.adFree[playerKey]=true;save(state);
    try {window.dispatchEvent(new CustomEvent('barberCommon:adFree',{detail:{playerId:playerKey}}));}catch(e){}
    const el=makeNode('bc-ad-gift',`<div class="bc-ad-gift-card" role="dialog" aria-modal="true" aria-label="הסרת פרסומות"><div class="bc-ad-gift-emoji">🎉✂️</div><h2>${COPY.gift}</h2><p>הפרסומות בוטלו בחינם בדפדפן הזה. תיהנו מהמשחק!</p><button type="button">${COPY.continue}</button></div>`);
    const button=el.querySelector('button');const close=()=>{el.remove();document.removeEventListener('keydown',keyClose)};
    const keyClose=e=>{if(e.key==='Escape')close()};button.addEventListener('click',close);document.addEventListener('keydown',keyClose);
    button.focus();
    return true;
  }
  function showInterstitial(options){
    if(currentOverlay)return currentOverlay.promise;
    insertStyle();
    const totalMs=Math.max(5,Number(options.durationSeconds)||15)*1000;
    const skipMs=Math.min(totalMs,Math.max(0,Number(options.skipAfterSeconds)||5)*1000);
    let resolveResult;
    const promise=new Promise(resolve=>{resolveResult=resolve;});
    const html=`<div class="bc-ad-panel" role="dialog" aria-modal="true" aria-label="פרסומת אבי וקוקו"><div class="bc-ad-head"><strong>✂️ ${COPY.title}</strong><span>מודעה · תוכן משחקי</span></div><div class="bc-ad-video"><img alt="פרסומת קומיקס של אבי וקוקו במספרה" loading="eager" decoding="async" /></div><div class="bc-ad-track"><div class="bc-ad-progress"></div></div><div class="bc-ad-countdown" aria-live="off">ניתן לדלג בעוד 5 שניות</div><button class="bc-ad-skip" type="button" disabled>דלג על המודעה</button><button class="bc-ad-remove" type="button">${COPY.remove}</button></div>`;
    const el=makeNode('bc-ad-cover',html);
    const img=el.querySelector('img');img.src=AD_IMAGE;
    const progress=el.querySelector('.bc-ad-progress'),skip=el.querySelector('.bc-ad-skip'),label=el.querySelector('.bc-ad-countdown'),remove=el.querySelector('.bc-ad-remove');
    let finished=false;const started=Date.now();let intervalId;
    const close=reason=>{if(finished)return;finished=true;clearInterval(intervalId);el.remove();currentOverlay=null;document.removeEventListener('keydown',onEscape);resolveResult({shown:true,reason});};
    const onEscape=e=>{if(e.key==='Escape'&&!skip.disabled)close('skipped')};
    function tick(){const elapsed=Date.now()-started;const leftSkip=Math.max(0,Math.ceil((skipMs-elapsed)/1000));const leftTotal=Math.max(0,Math.ceil((totalMs-elapsed)/1000));progress.style.width=(Math.min(1,elapsed/totalMs)*100)+'%';skip.disabled=elapsed<skipMs;label.textContent=elapsed<skipMs?'ניתן לדלג בעוד '+leftSkip+' שניות':'הפרסומת תסתיים בעוד '+leftTotal+' שניות';skip.textContent=elapsed<skipMs?'דלג בעוד '+leftSkip+' שניות':'דלג על המודעה ✕';if(elapsed>=totalMs)close('completed');}
    skip.addEventListener('click',()=>{if(!skip.disabled)close('skipped')});
    remove.addEventListener('click',()=>showGift(options.playerKey));
    document.addEventListener('keydown',onEscape);
    currentOverlay={promise,close};tick();intervalId=setInterval(tick,160);return promise;
  }
  function create(userConfig){
    const options={...DEFAULTS,...userConfig};
    const gameId=String(options.gameId||'barberGame').slice(0,60);
    const playerKey=()=>{let p=options.playerId;try{if(typeof p==='function')p=p();}catch(e){p='guest';}return normalizePlayer(p);};
    const isAdFree=()=>!!load().adFree[playerKey()];
    const removeAds=()=>showGift(playerKey());
    function recordGameOver(){
      const key=playerKey();const state=load();
      if(state.adFree[key])return Promise.resolve({shown:false,reason:'ad-free'});
      const id=gameId+'::'+key;
      state.deaths[id]=(Number(state.deaths[id])||0)+1;
      const interval=Math.max(1,Math.floor(Number(options.deathsPerAd)||2));
      const due=state.deaths[id]%interval===0;
      const enoughTime=Date.now()-(Number(state.lastShown[id])||0)>=Math.max(0,Number(options.minIntervalMs)||0);
      if(due&&enoughTime){state.lastShown[id]=Date.now();save(state);return showInterstitial({...options,playerKey:key});}
      save(state);return Promise.resolve({shown:false,reason:'not-due',deaths:state.deaths[id]});
    }
    return {recordGameOver,removeAds,isAdFree,getDeaths:()=>load().deaths[gameId+'::'+playerKey()]||0,playerId:playerKey};
  }
  root.BarberCommonAds=Object.freeze({create,version:'1.0.0'});
})(window);